module exponial_mod(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [31:0] m,\n    output reg [31:0] result,\n    output reg done\n);\n    // State definitions\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] CHECK_CASE = 4'd1;\n    localparam [3:0] BASE_CASE1 = 4'd2;\n    localparam [3:0] BASE_CASE2 = 4'd3;\n    localparam [3:0] BASE_CASE3 = 4'd4;\n    localparam [3:0] BASE_CASE4 = 4'd5;\n    localparam [3:0] PREP_RECUR = 4'd6;\n    localparam [3:0] COMPUTE_TOTIENT = 4'd7;\n    localparam [3:0] PUSH_STACK = 4'd8;\n    localparam [3:0] RECURSE = 4'd9;\n    localparam [3:0] MOD_EXP = 4'd10;\n    localparam [3:0] POP_STACK = 4'd11;\n    localparam [3:0] FINISH = 4'd12;\n    \n    // Stack depth = 16 levels (4-bit pointer)\n    reg [7:0] n_stack [0:15];\n    reg [31:0] m_stack [0:15];\n    reg [3:0] stack_ptr;\n    \n    reg [3:0] state, next_state;\n    reg [7:0] current_n;\n    reg [31:0] current_m;\n    reg [31:0] temp_val;\n    reg [31:0] totient;\n    \n    reg [15:0] cycle_counter;\n    localparam [15:0] MAX_CYCLES = 16'd1000;\n    \n    // Exponential base cases\n    function [31:0] base_case;\n        input [7:0] n_val;\n        input [31:0] mod_val;\n        case (n_val)\n            8'd1: base_case = 32'd1 % mod_val;\n            8'd2: base_case = 32'd2 % mod_val;\n            8'd3: base_case = 32'd9 % mod_val;\n            8'd4: base_case = (32'd1 << 18) % mod_val;  // 262144\n            default: base_case = 32'd0;\n        endcase\n    endfunction\n    \n    // Modular exponentiation helper\n    task mod_exp;\n        input [31:0] base;\n        input [31:0] exponent;\n        input [31:0] mod;\n        output reg [31:0] result;\n        reg [31:0] temp_base;\n        reg [63:0] temp;\n        integer i;\n        begin\n            result = 32'd1;\n            temp_base = base % mod;\n            for (i = 0; i < 32; i = i + 1) begin\n                if (exponent[i]) begin\n                    temp = result * temp_base;\n                    result = temp % mod;\n                end\n                temp = temp_base * temp_base;\n                temp_base = temp % mod;\n            end\n        end\n    endtask\n    \n    // Euler's totient approximation (simplified for implementation)\n    function [31:0] compute_totient;\n        input [31:0] m_val;\n        reg [31:0] i, count;\n        begin\n            if (m_val == 32'd1) \n                compute_totient = 32'd1;\n            else begin\n                count = 32'd0;\n                for (i = 0; i < m_val; i = i + 32'd1) \n                    if ($gcd(i, m_val) == 32'd1) \n                        count = count + 32'd1;\n                compute_totient = count;\n            end\n        end\n    endfunction\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            cycle_counter <= 16'd0;\n            stack_ptr <= 4'd0;\n            // Initialize stack arrays\n            for (int k = 0; k < 16; k = k + 1) begin\n                n_stack[k] <= 8'd0;\n                m_stack[k] <= 32'd0;\n            end\n        end else begin\n            cycle_counter <= cycle_counter + 16'd1;\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 16'd0;\n                    if (start) begin\n                        current_n <= n;\n                        current_m <= m;\n                        stack_ptr <= 4'd0;\n                        next_state <= CHECK_CASE;\n                    end\n                end\n                \n                CHECK_CASE: begin\n                    if (cycle_counter >= MAX_CYCLES) begin\n                        result <= 32'd0;\n                        next_state <= FINISH;\n                    end else if (current_n <= 8'd4) begin\n                        case (current_n)\n                            8'd1: next_state <= BASE_CASE1;\n                            8'd2: next_state <= BASE_CASE2;\n                            8'd3: next_state <= BASE_CASE3;\n                            8'd4: next_state <= BASE_CASE4;\n                            default: next_state <= FINISH;\n                        endcase\n                    end else begin\n                        next_state <= PREP_RECUR;\n                    end\n                end\n                \n                BASE_CASE1, BASE_CASE2, BASE_CASE3, BASE_CASE4: begin\n                    result <= base_case(current_n, current_m);\n                    next_state <= (stack_ptr > 4'd0) ? POP_STACK : FINISH;\n                end\n                \n                PREP_RECUR: begin\n                    totient <= compute_totient(current_m);\n                    next_state <= PUSH_STACK;\n                end\n                \n                PUSH_STACK: begin\n                    if (stack_ptr < 4'd15) begin\n                        n_stack[stack_ptr] <= current_n;\n                        m_stack[stack_ptr] <= current_m;\n                        stack_ptr <= stack_ptr + 4'd1;\n                        current_n <= current_n - 8'd1;\n                        current_m <= totient;\n                        next_state <= CHECK_CASE;\n                    end else begin\n                        // Max recursion depth reached\n                        next_state <= FINISH;\n                    end\n                end\n                \n                POP_STACK: begin\n                    if (stack_ptr > 4'd0) begin\n                        stack_ptr <= stack_ptr - 4'd1;\n                        current_n <= n_stack[stack_ptr-1];\n                        temp_val <= result;\n                        current_m <= m_stack[stack_ptr-1];\n                        next_state <= MOD_EXP;\n                    end else begin\n                        next_state <= FINISH;\n                    end\n                end\n                \n                MOD_EXP: begin\n                    // Compute current_n ^ temp_val mod current_m\n                    mod_exp(current_n, temp_val, current_m, result);\n                    next_state <= POP_STACK;\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                \n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n    \nendmodule